// Exact private worker parser, pre-discovery session gate and child refusal path.
// These cases never admit a real Steam scope or contact a CDP endpoint.
#include "../native/decky_binding_worker.h"
#include <filesystem>
#include <fstream>
#include <iostream>
namespace {
using J=nlohmann::json;
using namespace ymcc::deckybinding::worker;
J request(){return{{"schema",schema},{"id",std::string(32,'a')},{"generation","17"},{"steam",{{"root","C:/source-fixture/Steam"},{"pid",GetCurrentProcessId()},{"created","123456789012345678"},{"account",12345678},{"windowsSession",0}}},{"bootstrap",{{"endpoint","ws://127.0.0.1:1/mirror"},{"token",std::string(64,'b')},{"runId",std::string(32,'c')}}},{"requireFreshContext",true},{"retainedFrontendOnly",false}};}
void need(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
bool refuses(const J& value){try{(void)parse(value.dump());return false;}catch(const std::exception&){return true;}}
}
int main(int argc,char** argv){
    if(argc!=2)return 3;J cases=J::array();
    const auto test=[&](const char* name,const auto& body){try{body();cases.push_back({{"name",name},{"passed",true}});}catch(const std::exception& e){cases.push_back({{"name",name},{"passed",false},{"reason",e.what()}});}};
    test("exact-request-retains-full-identity-and-string-birth",[]{const auto r=parse(request().dump());need(r.id==std::string(32,'a')&&r.generation==17&&r.steam.pid==GetCurrentProcessId()&&r.steam.created==123456789012345678ULL&&r.steam.account==12345678&&r.steam.root==L"c:\\source-fixture\\steam","identity-changed");});
    test("private-request-rejects-missing-extra-and-wrong-fields",[]{for(const auto* key:{"id","generation","steam","bootstrap","requireFreshContext","retainedFrontendOnly"}){auto value=request();value.erase(key);need(refuses(value),"missing-field-accepted");}auto value=request();value["extra"]=true;need(refuses(value),"extra-field-accepted");value=request();value["schema"]="other";need(refuses(value),"wrong-schema-accepted");});
    test("full-birth-and-generation-never-inferred-from-floats",[]{for(const auto& bad:J::array({0,-1,1.5,"0","-1","18446744073709551616","1x","",nullptr})){auto value=request();value["steam"]["created"]=bad;need(refuses(value),"bad-birth-accepted");value=request();value["generation"]=bad;need(refuses(value),"bad-generation-accepted");}});
    test("pid-account-and-session-have-dword-range",[]{for(const auto& bad:J::array({-1,1.5,4294967296ULL,"12",nullptr})){for(const auto* field:{"pid","account","windowsSession"}){auto value=request();value["steam"][field]=bad;need(refuses(value),"bad-dword-accepted");}}for(const auto* field:{"pid","account"}){auto value=request();value["steam"][field]=0;need(refuses(value),"zero-identity-accepted");}});
    test("paths-have-no-nul-relative-or-invalid-utf8",[]{for(const auto& bad:std::vector<std::string>{"","relative/Steam",std::string("C:/Steam\0other",14)}){auto value=request();value["steam"]["root"]=bad;need(refuses(value),"bad-path-accepted");}auto bytes=request().dump();const auto at=bytes.find("source-fixture");need(at!=std::string::npos,"root-fixture");bytes[at]=static_cast<char>(0xff);bool refused=false;try{(void)parse(bytes);}catch(const std::exception&){refused=true;}need(refused,"invalid-utf8-accepted");});
    test("retained-and-first-load-authority-do-not-mix",[]{auto value=request();value["retainedFrontendOnly"]=true;need(refuses(value),"conflicting-authority-accepted");value["requireFreshContext"]=false;need(refuses(value),"retained-without-build-accepted");value["bootstrap"]["frontendBuildId"]=std::string(64,'d');need(!refuses(value),"valid-retained-refused");});
    test("nonce-token-and-runid-remain-exact",[]{for(const auto* field:{"id","token","runId"}){auto value=request();if(std::string(field)=="id")value[field]="not-a-nonce";else value["bootstrap"][field]="not-a-nonce";need(refuses(value),"bad-correlation-accepted");}});
    test("duplicate-root-and-nested-keys-rejected",[]{auto bytes=request().dump();bytes.insert(1,"\"schema\":\"ymcc.decky.binding-worker.v1\",");bool refused=false;try{(void)parse(bytes);}catch(const std::exception&){refused=true;}need(refused,"duplicate-root-key-accepted");bytes=request().dump();const auto pos=bytes.find("\"pid\":");need(pos!=std::string::npos,"pid-fixture");bytes.insert(pos,"\"pid\":1,");refused=false;try{(void)parse(bytes);}catch(const std::exception&){refused=true;}need(refused,"duplicate-nested-key-accepted");});
    test("oversized-input-rejected-before-json-allocation",[]{bool refused=false;try{(void)parse(std::string(maximumRequestBytes+1,' '));}catch(const std::runtime_error& e){refused=std::string(e.what())=="mirror-bootstrap-worker-request-size";}need(refused,"large-request-accepted");});
    test("failed-fixed-session-guard-stops-before-discovery-or-injection",[]{unsigned calls=0;const auto result=ymcc::deckymirror::injectBootstrap(L"C:/source-fixture/Steam",request()["bootstrap"],{},{},{},{},false,false,GetCurrentProcessId(),[&]{++calls;return false;});need(calls==1&&result.at("reason")=="mirror-bootstrap-session-changed"&&result.at("mutated")==false,"fixed-session-guard-not-obeyed");});
    test("pre-canceled-child-sends-one-nonmutating-refusal",[]{ymcc::deckybinding::worker::Event cancel;SetEvent(cancel.value);J packets=J::array();const auto code=run(request().dump(),cancel.value,[&](const J& row){packets.push_back(row);return true;});need(code==2&&packets.size()==1&&packets[0]["kind"]=="result"&&packets[0]["detail"]["reason"]=="mirror-bootstrap-canceled"&&packets[0]["detail"]["mutated"]==false,"canceled-child-wrong-result");need(packets.dump().find(std::string(64,'b'))==std::string::npos,"private-bootstrap-token-exported");});
    test("unqualified-scope-never-starts-bootstrap-or-claims-recovery",[]{ymcc::deckybinding::worker::Event cancel;J packets=J::array();const auto code=run(request().dump(),cancel.value,[&](const J& row){packets.push_back(row);return true;});need(code==2&&packets.size()==1&&packets[0]["detail"]["reason"]=="mirror-bootstrap-session-changed"&&packets[0]["detail"]["mutated"]==false,"unqualified-scope-admitted");});
    test("malformed-request-never-echoes-private-input",[]{ymcc::deckybinding::worker::Event cancel;unsigned packets=0;const auto code=run("private-invalid-payload",cancel.value,[&](const J&){++packets;return true;});need(code==2&&packets==0,"malformed-private-input-published");});
    const auto passed=std::count_if(cases.begin(),cases.end(),[](const J& row){return row.at("passed").get<bool>();});const bool ok=static_cast<std::size_t>(passed)==cases.size();
    const J result={{"schema","ymcc.binding-worker-protocol-actual-consumer.v1"},{"passed",ok},{"tests",cases.size()},{"passedCount",passed},{"cases",cases},{"productionParserAndRefusalExecuted",true},{"actualValidSteamInjectionTested",false},{"realSteamOrDeviceActions",0},{"fullRuntimeBindingMigrationCompleted",false},{"fieldRecoveryVerified",false}};
    std::ofstream out(std::filesystem::absolute(argv[1]),std::ios::binary);out<<result.dump(2)<<'\n';out.close();std::cout<<"WORKER_PROTOCOL cases="<<cases.size()<<" passed="<<passed<<'\n';return ok?0:2;
}
